/* Portfolio photographs from Hands On Design's company presentation (handsondesign.in), compressed for the demo */
(function () {
  const H = window.HOD;
  const B64 = {"banquet_gold": "", "banquet_hall": "", "bed_jaali": "", "bed_lux": "", "bed_suite": "", "bed_twin": "", "bed_warm": "", "buffet_gold": "", "cafe_blue": "", "cafe_brick": "", "cafe_chevron": "", "cafe_mural": "", "cowork_bright": "", "dining_arches": "", "dining_booths": "", "lobby_marble": "", "lounge_warm": "", "pantry_geo": "", "showroom_arch": "", "showroom_white": ""};
  const SETS = {"p1": ["bed_jaali", "bed_lux", "lounge_warm"], "p2": ["bed_suite", "bed_twin", "bed_warm"], "p3": ["lobby_marble", "lounge_warm", "pantry_geo"], "p4": ["dining_arches", "dining_booths", "cafe_mural"], "p5": ["bed_warm", "bed_lux", "banquet_hall"], "p6": ["bed_lux", "bed_jaali", "bed_suite"], "p7": ["showroom_white", "showroom_arch", "lobby_marble"], "p8": ["banquet_gold", "banquet_hall", "buffet_gold"], "p9": ["bed_twin", "bed_suite", "bed_warm"], "p10": ["cowork_bright", "pantry_geo", "lounge_warm"], "p11": ["bed_warm", "bed_jaali", "lobby_marble"], "p12": ["cafe_blue", "cafe_brick", "cafe_chevron"]};
  const URLS = {};
  Object.keys(B64).forEach(k => { try { const bin = atob(B64[k]), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); URLS[k] = URL.createObjectURL(new Blob([u], { type: 'image/webp' })); } catch (e) { URLS[k] = 'data:image/webp;base64,' + B64[k]; } });
  const KEYS = Object.keys(URLS);
  H.photoKeys = KEYS;
  H.photoUrl = k => URLS[k] || URLS[KEYS[0]];
  H.projPhotos = pid => (SETS[pid] || []).filter(k => URLS[k]).concat(KEYS.filter(k => !(SETS[pid] || []).includes(k)));
  H.cover = (pid, i) => { const L = H.projPhotos(pid); return URLS[L[(i || 0) % L.length]]; };
  const svgThumb = H.thumb;
  H.thumbSvg = svgThumb;
  // photo for a render or site picture; picks from the project's own set when the project is known
  H.thumb = (seed, kind, label, pid) => {
    if (kind === 'board') return svgThumb(seed, kind, label);
    const L = pid ? H.projPhotos(pid).slice(0, 3) : KEYS;
    const k = L[Math.abs(seed | 0) % L.length];
    return `<img class="ph${kind === 'site' ? ' site' : ''}" src="${URLS[k]}" alt="${(label || (kind === 'site' ? 'Site photo' : 'Design render')).replace(/"/g, '&quot;')}" loading="lazy" decoding="async">`;
  };
})();
